    async def validate_address(
        self,
        *,
        first_line: typing.Optional[str] = OMIT,
        second_line: typing.Optional[str] = OMIT,
        third_line: typing.Optional[str] = OMIT,
        city: typing.Optional[str] = OMIT,
        post_code: typing.Optional[str] = OMIT,
        state: typing.Optional[str] = OMIT,
        country: typing.Optional[str] = OMIT,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> ValidateAddressOrdersResponse:
        """
        Validates the format of an address for a card order. Make sure to follow country-specific address fields and validation as described in the [card address validation guide](/guides/developer/api-guides/card-address-validation).

        For card creation, the `address` requirement depends on the card type:

        - **Physical Cards (Required)**: Used as the delivery address to ship the card and for AVS checks in countries where required.

        - **Virtual Cards (Optional)**: If provided, this acts as the billing address. If omitted, the profile address is used as the fallback. In either scenario, the address is used for AVS checks in countries where required.

        {% admonition type="warning" %}
        We do not support PO BOX addresses.
        {% /admonition %}

        Parameters
        ----------
        first_line : typing.Optional[str]
            Card holder's address (max 30 characters).

        second_line : typing.Optional[str]
            Card holder's address (max 30 characters).

        third_line : typing.Optional[str]
            Card holder's address (max 30 characters).

        city : typing.Optional[str]
            Card holder's city (max 30 characters).

        post_code : typing.Optional[str]
            Card holder's postal code (max 10 characters).

        state : typing.Optional[str]
            Card holder's state (max 30 characters).

        country : typing.Optional[str]
            Card holder's country (ISO 3166-1 alpha-2, max 2 characters).

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        ValidateAddressOrdersResponse
            OK - Validation result returned. An empty errors collection means the address is valid.

        Examples
        --------
        import asyncio

        from wise_sdk.generated import AsyncWiseClient
        from wise_sdk.generated.environment import WiseClientEnvironment

        client = AsyncWiseClient(
            external_correlation_id="YOUR_EXTERNAL_CORRELATION_ID",
            client_id="YOUR_CLIENT_ID",
            client_secret="YOUR_CLIENT_SECRET",
            access_token="YOUR_ACCESS_TOKEN",
            environment=WiseClientEnvironment.SANDBOX,
        )


        async def main() -> None:
            await client.cards.orders.validate_address()


        asyncio.run(main())
        """
        _response = await self._raw_client.validate_address(
            first_line=first_line,
            second_line=second_line,
            third_line=third_line,
            city=city,
            post_code=post_code,
            state=state,
            country=country,
            request_options=request_options,
        )
        return _response.data
